mapper.insert:
BEGIN

	INSERT
	  INTO
		   RESTAURANT (
						 RESTAURANT_ID
					   , ROOM_ID
					   , NAME
					   , SOURCE
					   , ADDRESS
					   , LAT
					   , LNG
					   , ADDED_BY
					   , CREATED_AT
					   , KAKAO_PLACE_ID
					   , CATEGORY
					   , ROAD_ADDRESS
					   , PHONE
					   , PLACE_URL
					   )
	VALUES
		   (
			 SEQ_RESTAURANT.NEXTVAL
		   , (
			   SELECT
					  ROOM_ID
				 FROM
					  ROOM
				WHERE
					  ROOM_UUID = #{item.roomUuid}
			 )
		   , #{item.name}
		   , #{item.source}
		   , #{item.address}
		   , #{item.lat}
		   , #{item.lng}
		   , #{item.participantId}
		   , SYSDATE
		   , #{item.kakaoPlaceId}
		   , #{item.category}
		   , #{item.roadAddress}
		   , #{item.phone}
		   , #{item.placeUrl}
		   );

END;
